create procedure test_resignal()
begin
DECLARE CONTINUE HANDLER for sqlwarning
begin
select "handler called";
RESIGNAL SET
MESSAGE_TEXT = "RESIGNAL of a warning",
MYSQL_ERRNO = 55555 ;
end;

insert into t_warn set a= 9999999999999999;
end

